def occasions(name, cat=None, price=0):
    o=[]
    if cat=='Restaurants':
        if price>=4: o=['Romantic','Date night']
        elif price==3: o=['Date night']
        elif price==2: o=['Casual','Date night']
        else: o=['Casual']
        if name in ('Bestia','Bavel','Jon & Vinny\'s','Pizzeria Mozza','Mother Wolf','Girl & the Goat LA','Yangban','Park\'s BBQ','Kang Ho Dong Baekjeong','Quarters','Sun Nong Dan','Din Tai Fung','Sea Harbour','Lunasia','Newport Seafood','Grand Central Market','Mercado La Paloma','Guelaguetza','Casa Vega','Dan Tana\'s','Craig\'s','Nobu Malibu','Catch LA','Roscoe\'s House of Chicken \'N Waffles'): o=o+['Group']
    elif cat=='Cafés': o=['Date night','Casual'] if price>=2 else ['Casual']
    elif cat=='Speakeasies': o=['Date night','Late night']
    elif cat=='Bars':
        o=['Late night'] if price<=1 else ['Date night','Late night']
        if 'Brew' in name or name in ('Golden Road','Angel City','Boomtown','Mumford','Smog City','Monkish','Three Weavers','Brouwerij West'): o=['Group','Casual']
        if name in ('Thunderbolt','Death & Co LA','Genever','The Varnish','The Roger Room','Tower Bar','Chateau Marmont','Polo Lounge','Bar Nineteen12','Melody','Voodoo Vin','Bar Bandini','Tabula Rasa','Esters','Tilda','Bar Etoile'): o=['Romantic','Date night']
    elif cat=='Rooftops': o=['Date night','Group']
    elif cat=='Coffee': o=['Sweets','Brunch']
    elif cat=='Brunch': o=['Brunch']
    elif cat=='Off-beat': o=['Casual']
    elif cat=='Bakeries': o=['Sweets','Brunch']
    elif cat=='Dessert': o=['Sweets']
    elif cat=='Scene': o=['Group','Date night'] if price<=3 else ['Romantic','Group']
    elif cat=='Nightlife': o=['Late night','Group']
    return o
